"""Author PRE_A1-U11 only; preserve stable IDs and earlier lexical keys."""
import json,copy,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
KIT=ROOT/'plans/daily-practice-authoring'
OUT=Path(__file__).parent/'packages/PRE_A1'
level=json.loads((KIT/'levels/PRE_A1.plan.json').read_text())['level']
plan=level['units'][10]
W={}
for source in [OUT/f'PRE_A1-U{n:02}.v1.json' for n in range(10,1,-1)]+[KIT/'examples/PRE_A1-U01.v2.json']:
 for s in json.loads(source.read_text())['sessions']:
  for w in s['vocabulary']:W.setdefault(w['id'],copy.deepcopy(w))
for w in W.values():
 if 'example' not in w:w['example']=dict(fr=w['fr'],ru=w['ru'][0],transcription_ru=w['transcription_ru'])
OLD=set(W);FIRST={};S=[]
U='PRE_A1.U11.UNDERSTAND';A='PRE_A1.U11.APPLY'
OBJECTIVES={o['id']:o for u in level['units'] for o in u['objectives']}

def ru(t): return dict(text=t,text_lang='ru')

def fr(t,p): return dict(text=t,text_lang='fr',transcription_ru=p)

def ex(f,r,p): return dict(fr=f,ru=r,transcription_ru=p)

def sound(f,p): return dict(text=f,transcription_ru=p,lang='fr-FR',asset_id=None)

def wc(w): return fr(W[w]['fr'],W[w]['transcription_ru'])

def fb(g,b): return dict(correct=g,incorrect=b)

def opts(v): return [dict(id=f'c{i}',**(ru(t) if isinstance(t,str) else t)) for i,t in enumerate(v)]

def rev(i,p,cs,a,g,b): return dict(id=i,type='single_choice',instruction='Выберите один ответ.',prompt=p,choices=opts(cs),correct_choice_id=f'c{a}',feedback=fb(g,b))

def start(n,d,vs):
 p=plan['sessions'][n-1]; s={k:copy.deepcopy(p[k]) for k in ['id','title','order','kind','prerequisite_ids']}
 s.update(version=1,level='PRE_A1',unit_id=plan['id'],description=d,duration_minutes=6,objectives=copy.deepcopy(plan['objectives']),skills=[],vocabulary=[copy.deepcopy(W[w]) for w in vs],tasks=[],introductions=[]); S.append(s); return s

def base(s,sk,gs,vs,av,ins,p,g,b):
 for o in gs:
  if o not in [x['id'] for x in s['objectives']]: s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))
 if sk not in s['skills']: s['skills'].append(sk)
 t=dict(id=f'Q{len(s["tasks"])+1:02}',instruction=ins,prompt=p,feedback=fb(g,b),objective_ids=gs,skill=sk,vocabulary_ids=vs,assessed_vocabulary_ids=av); s['tasks'].append(t); return t

def choose(s,sk,gs,vs,av,ins,p,cs,a,g,b):
 t=base(s,sk,gs,vs,av,ins,p,g,b); t.update(type='single_choice',choices=opts(cs),correct_choice_id=f'c{a}'); return t

def listen(s,gs,vs,av,q,f,p,cs,a,g,b):
 return choose(s,'listening',gs,vs,av,'Прослушайте и выберите ответ.',dict(**ru(q),audio=sound(f,p)),cs,a,g,b)

def intro(s,n,t,vs,ns=(),au=None):
 i=dict(id=f'I{len(s["introductions"])+1:02}',before_task_id=f'Q{n:02}',text=t,vocabulary_ids=vs)
 if ns:i['pronunciation_notes']=[dict(fr=f,transcription_ru=p) for f,p in ns]
 if au:i['audio']=sound(*au)
 s['introductions'].append(i)

def pairs(s,gs,rows,g,b):
 vs=[w for w,r in rows]; t=base(s,'vocabulary',gs,vs,vs,'Соедините каждую карточку с её значением.',ru('Используйте все карточки по одному разу.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**wc(w)) for i,(w,r) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(w,r) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=[w]) for i,(w,r) in enumerate(rows)])

def order(s,gs,vs,av,ins,ts,f,p,g,b):
 t=base(s,'sentence_building',gs,vs,av,ins,ru('Нажимайте на карточки в нужном порядке.'),g,b); tokens=[dict(id=f't{i}',**fr(f,p)) for i,(f,p) in enumerate(ts)]
 t.update(type='word_order',tokens=list(reversed(tokens)),accepted_orders=[[x['id'] for x in tokens]],completed_phrases=[dict(fr=f,transcription_ru=p)])

def fill(s,gs,vs,av,ins,bef,bp,aft,ap,cs,a,f,p,g,b):
 t=base(s,'vocabulary',gs,vs,av,ins,ru('Выберите одну карточку для пропуска.'),g,b)
 t.update(type='fill_blank',input_mode='choice',text_before=bef,text_before_transcription_ru=bp,text_after=aft,text_after_transcription_ru=ap,choices=opts(cs),correct_choice_id=f'c{a}',completed_phrases=[dict(fr=f,transcription_ru=p)])

 return t

def page(s,blocks):
 s['public_page']=dict(slug=s['id'].lower().replace('_','-'),summary=s['description'],seo_title=s['title']+' — французский с нуля',seo_description=s['description'],explanation_blocks=[dict(heading=h,paragraphs=ps,examples=es) for h,ps,es in blocks])

def grammar(t):
 t['skill']='grammar'
 return t

def addword(i,key,f,r,p,e,n,reviews):
 W[i]=dict(id=i,lexeme_key=key,fr=f,ru=[r],transcription_ru=p,example=e,review_items=reviews);FIRST[i]=n
addword('je-veux','fr:je-veux:want','je veux','Я хочу (прямое сообщение о желании)','жё вё́',ex('Je veux une pomme.','Я хочу яблоко.','жё вё юн по́м'),1,[rev('je-veux-meaning',fr('Je veux une pomme.','жё вё юн по́м'),['Мне нравится яблоко.','Я хочу яблоко.','Вот яблоко.'],1,'Говорящий прямо сообщает, что хочет яблоко.','Это сообщение о желании, а не о вкусе продукта или его передаче.'),rev('je-veux-use',ru('В задании нужно прямо сказать «Я хочу хлеба». Какую изученную форму выбрать?'),[fr('J’aime le pain.','жэм лё пэ́(н)'),fr('Je voudrais du pain.','жё вудрэ дю пэ́(н)'),fr('Je veux du pain.','жё вё дю пэ́(н)')],2,'Выбрано прямое сообщение «Я хочу».','Нужна именно прямая форма; предпочтение и более мягкая просьба имеют другие значения.')])
addword('donnez-moi','fr:donnez-moi:give-request','donnez-moi','Дайте мне','донэ муа́',ex('Donnez-moi un livre, s’il vous plaît.','Дайте мне книгу, пожалуйста.','донэ муа э(н) ливр, силь ву плэ́'),2,[rev('donnez-moi-meaning',fr('Donnez-moi un livre, s’il vous plaît.','донэ муа э(н) ливр, силь ву плэ́'),['Я хочу книгу.','Мне нравится книга.','Дайте мне книгу, пожалуйста.'],2,'Это просьба передать книгу.','Здесь прямо просят дать книгу, а не только сообщают желание или предпочтение.'),rev('donnez-moi-use',ru('Собеседник готов передать книгу. Нужно сказать именно «Дайте мне книгу, пожалуйста». Какую реплику выбрать?'),[fr('Donnez-moi un livre, s’il vous plaît.','донэ муа э(н) ливр, силь ву плэ́'),fr('Je veux un livre.','жё вё э(н) ли́вр'),fr('Je voudrais un livre.','жё вудрэ э(н) ли́вр')],0,'Выбрана изученная прямая просьба передать вещь.','Нужна формулировка «Дайте мне»; два других начала выражают желание иначе.')])
addword('voila','fr:voila:presenting','voilà','Вот, пожалуйста (при передаче)','вуаля́',ex('Voilà.','Вот, пожалуйста.','вуаля́'),2,[rev('voila-meaning',fr('Voilà.','вуаля́'),['Дайте мне.','Вот, пожалуйста.','Я хочу.'],1,'В показанной ситуации эта реплика сопровождает передачу вещи.','Это реплика при передаче, а не просьба дать вещь или сообщение о желании.'),rev('voila-use',ru('В учебном диалоге сотрудник передаёт уже выбранную книгу. Какую изученную реплику произнести при передаче?'),[fr('Je voudrais un livre.','жё вудрэ э(н) ли́вр'),fr('Voilà.','вуаля́'),fr('Donnez-moi un livre.','донэ муа э(н) ли́вр')],1,'Реплика подходит к моменту передачи.','Нужна реплика передачи; две другие относятся к просьбе получить книгу.')])
addword('ou','fr:ou:alternative-conjunction','ou','или (при предложении альтернатив)','у',ex('Du pain ou du fromage ?','Хлеб или сыр?','дю пэ(н) у дю фрома́ж?'),3,[rev('ou-meaning',fr('Du pain ou du fromage ?','дю пэ(н) у дю фрома́ж?'),['Хлеб и сыр как две названные позиции.','Предложение выбрать хлеб или сыр.','Просьба ещё сыра.'],1,'В этой ситуации предложены две альтернативы.','Это выбор «или», а не соединение двух позиций и не добавка.'),rev('ou-use',ru('В упражнении предлагаются яблоко или апельсин. Какое слово означает «или» между вариантами?'),[fr('et','э'),fr('ou','у'),wc('merci')],1,'Слово связывает альтернативы.','Нужно «или»; соединение «и» и благодарность имеют другой смысл.')])
addword('je-prends','fr:je-prends:choosing-item','je prends','Я беру (сообщение о выборе)','жё пра́(н)',ex('Je prends une pomme.','Я беру яблоко.','жё пра(н) юн по́м'),3,[rev('je-prends-meaning',fr('Je prends une pomme.','жё пра(н) юн по́м'),['Я беру яблоко.','Мне нравятся яблоки.','Дайте мне яблоко.'],0,'Говорящий сообщает свой выбор.','Это «я беру», а не общее предпочтение или формулировка «дайте мне».'),rev('je-prends-use',ru('Вы выбрали яблоко и должны сообщить выбор словами «Я беру яблоко». Какую реплику выбрать?'),[fr('J’aime les pommes.','жэм лэ по́м'),fr('Donnez-moi une pomme.','донэ муа юн по́м'),fr('Je prends une pomme.','жё пра(н) юн по́м')],2,'Реплика прямо сообщает выбранную позицию.','Нужна изученная форма «я беру»; предпочтение и просьба передать — другие формулировки.')])
addword('encore','fr:encore:additional-quantity','encore','ещё (добавка того же)','а(н)ко́р',ex('Je voudrais encore du pain.','Мне бы хотелось ещё хлеба.','жё вудрэ а(н)кор дю пэ́(н)'),4,[rev('encore-meaning',fr('Je voudrais encore du pain.','жё вудрэ а(н)кор дю пэ́(н)'),['Больше ничего не нужно.','Просит ещё хлеба.','Выбирает между хлебом и сыром.'],1,'Говорящий просит добавку хлеба.','Это просьба ещё, а не завершение заказа или выбор между двумя позициями.'),rev('encore-use',ru('Нужно прямо сказать «ещё хлеба» без уточнения, насколько больше. Какая реплика подходит?'),[fr('C’est tout, merci.','сэ ту, мэрси́'),fr('Je voudrais encore du pain.','жё вудрэ а(н)кор дю пэ́(н)'),fr('Je prends du fromage.','жё пра(н) дю фрома́ж')],1,'Реплика просит добавку того же продукта.','Нужна просьба ещё хлеба; завершение заказа и выбор сыра не соответствуют условию.')])
